def graphemes(text: str) -> Generator[str, None, None]:
    """Split text into grapheme clusters."""
    if not text:
        return

    i = 0
    while i < len(text):
        start = i
        i += 1
        while i < len(text) and (
            ord(text[i]) == 0x200D or # ZWJ
            0x0300 <= ord(text[i]) <= 0x036F or # Combining Diacritical Marks
            0x1AB0 <= ord(text[i]) <= 0x1AFF or # Combining Diacritical Marks Extended
            0x1DC0 <= ord(text[i]) <= 0x1DFF or # Combining Diacritical Marks Supplement
            0x20D0 <= ord(text[i]) <= 0x20FF or # Combining Diacritical Marks for Symbols
            0xFE00 <= ord(text[i]) <= 0xFE0F    # Variation Selectors
        ):
            i += 1
            if i < len(text) and ord(text[i-1]) == 0x200D:
                i += 1
        yield text[start:i]

