    if cell_size == total:
        return text
    if cell_size < total:
        return text + " " * (total - cell_size)

    # We need to truncate the text to fit within 'total' cells.
    # We iterate over graphemes to ensure we don't split a grapheme.
    current_len = 0
    result = []
    for g in graphemes(text):
        g_len = cell_len(g)
        if current_len + g_len <= total:
            result.append(g)
            current_len += g_len
        else:
            break

    return "".join(result)
